// Sitemap for /intent/:slug pages generated by the Search Intent Engine.
import { corsHeaders } from "npm:@supabase/supabase-js@2/cors";
import { createClient } from "npm:@supabase/supabase-js@2";

const BASE = "https://marketrends.no";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);

  const { data } = await supabase.from("search_intents")
    .select("target_slug, updated_at, priority_score")
    .eq("content_status", "published")
    .order("priority_score", { ascending: false })
    .limit(5000);

  const urls = (data || []).map((r: any) => `
  <url>
    <loc>${BASE}/intent/${r.target_slug}</loc>
    <lastmod>${new Date(r.updated_at || Date.now()).toISOString()}</lastmod>
    <changefreq>weekly</changefreq>
    <priority>${(Math.max(0.3, Math.min(0.9, (r.priority_score || 50) / 100))).toFixed(2)}</priority>
  </url>`).join("");

  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls}
</urlset>`;

  return new Response(xml, {
    headers: { ...corsHeaders, "Content-Type": "application/xml; charset=utf-8" },
  });
});
